// ===== Settings =====
const PBN_API_URL = 'http://127.0.0.1:3000'; // the API on the same machine as n8n
const PALETTE = 'darlart-v2';
const DIFFICULTY = 'medium'; // easy, medium or hard: the same level for every order
const DEFAULT_COLORS = 24;
const DEFAULT_FORMAT = 'a4'; // used when a digital order doesn't name its print format
// Digital products: the customer prints the template, so the canvas IS the sheet of paper (A series, 1:V2)
const FORMATS = {
  a4: { canvasSize: '21x29.7', paperSize: 'a4', label: 'A4' },
  a3: { canvasSize: '29.7x42', paperSize: 'a3', label: 'A3' },
  a2: { canvasSize: '42x59.4', paperSize: 'a2', label: 'A2' },
};
// Line item properties written by the Darl'Art crop widget (shopify/ folder), lowercase, matched with "includes"
const PHOTO_PROPERTIES = ['photo', 'image', 'upload', 'fichier'];
const SIZE_PROPERTIES = ['format', 'canvas size', 'taille', 'size'];
const ORIENTATION_PROPERTIES = ['orientation'];
const COLOR_PROPERTIES = ['colors', 'couleurs', 'color', 'couleur'];
// ====================

const norm = (s) => String(s || '').trim().toLowerCase();
// "A3" or "Format A3 (29,7 x 42 cm)" -> a3. Always tried BEFORE findSize, which would read "29.7x42" as "29x42".
const findFormat = (text) => { const m = String(text || '').match(/\ba\s*([234])\b/i); return m ? `a${m[1]}` : ''; };
const findSize = (text) => { const m = String(text || '').match(/(\d{2,3}(?:[.,]\d+)?)\s*[x×*]\s*(\d{2,3}(?:[.,]\d+)?)/i); return m ? `${m[1].replace(',', '.')}x${m[2].replace(',', '.')}` : ''; };
const findColors = (text) => { const m = String(text || '').match(/\b(12|24|36|48)\b/); return m ? Number(m[1]) : 0; };
const findOrientation = (text) => { const t = norm(text); return /paysage|landscape/.test(t) ? 'landscape' : (/portrait/.test(t) ? 'portrait' : ''); };
// the photo is already cropped by the customer: the API only trims the pixels that don't fit the exact ratio
const base = { apiUrl: PBN_API_URL, palette: PALETTE, difficulty: DIFFICULTY, cropMode: 'center' };
const out = [];

for (const item of $input.all()) {
  // the webhook node wraps the payload in "body"
  const data = item.json.body && item.json.body.orderId ? item.json.body : item.json;

  // Generic payload: { orderId, paid, photoUrl (already cropped), format ("A3") or canvasSize, orientation, colors, customerEmail? }
  if (data.orderId && !data.line_items) {
    if (data.paid !== true && data.paid !== 'true') continue; // only paid orders
    const format = FORMATS[findFormat(data.format || data.canvasSize)] || null;
    const canvasSize = format ? format.canvasSize : findSize(data.canvasSize);
    const issues = [];
    if (!/^https?:\/\//i.test(data.photoUrl || '')) issues.push('missing photo URL');
    if (!canvasSize) issues.push('missing or invalid print format');
    out.push({ json: { ...base, orderId: String(data.orderId).replace(/^#/, ''), shopifyOrderId: '', photoUrl: data.photoUrl || '', canvasSize, paperSize: format ? format.paperSize : FORMATS[DEFAULT_FORMAT].paperSize, format: format ? format.label : canvasSize, colors: findColors(data.colors) || DEFAULT_COLORS, orientation: findOrientation(data.orientation) || 'auto', customerEmail: data.customerEmail || '', ready: issues.length === 0, issues: issues.join(', ') } });
    continue;
  }

  // Shopify order (orders/paid)
  if (data.financial_status !== 'paid') continue;
  const orderId = String(data.name || data.order_number || data.id).replace(/^#/, '');
  const lines = [];
  for (const line of data.line_items || []) {
    const props = (line.properties || []).map((p) => ({ name: norm(p.name), value: String(p.value || '') }));
    const prop = (names) => { const p = props.find((x) => names.some((n) => x.name.includes(n)) && x.value); return p ? p.value : ''; };
    const photo = props.find((x) => PHOTO_PROPERTIES.some((n) => x.name.includes(n)) && /^https?:\/\//i.test(x.value))
      || props.find((x) => /^https?:\/\/\S+\.(jpe?g|png|webp)(\?|$)/i.test(x.value));
    // digital orders name a print format; older canvas orders still carry a size in cm
    const format = FORMATS[findFormat(prop(SIZE_PROPERTIES)) || findFormat(line.variant_title) || findFormat(line.title)] || null;
    const canvasSize = format ? format.canvasSize : (findSize(prop(SIZE_PROPERTIES)) || findSize(line.variant_title) || findSize(line.title));
    if (!photo && !canvasSize) continue; // not a paint by numbers product
    const issues = [];
    if (!photo) issues.push('missing photo upload');
    if (!canvasSize) issues.push('missing or invalid print format');
    lines.push({
      ...base,
      product: line.title,
      photoUrl: photo ? photo.value : '',
      canvasSize,
      paperSize: format ? format.paperSize : FORMATS[DEFAULT_FORMAT].paperSize,
      format: format ? format.label : canvasSize,
      colors: findColors(prop(COLOR_PROPERTIES)) || findColors(line.variant_title) || DEFAULT_COLORS,
      // chosen by the customer in the widget; "auto" follows the cropped photo, which already has the right shape
      orientation: findOrientation(prop(ORIENTATION_PROPERTIES)) || findOrientation(line.variant_title) || 'auto',
      customerEmail: data.email || '',
      shopifyOrderId: data.id ? String(data.id) : '',
      ready: issues.length === 0,
      issues: issues.join(', '),
    });
  }
  // one template per photo: suffix the order number when an order has several
  lines.forEach((line, index) => out.push({ json: { ...line, orderId: lines.length > 1 ? `${orderId}-${index + 1}` : orderId } }));
}

return out;

// One item per generated file (PDF, SVG, preview, palette)
const job = $('Wait for job').first().json.body;
const order = $('Loop over photos').first().json;
const folderId = $input.first().json.id;
return job.result.files.map((file) => ({
  json: {
    url: file.url,
    downloadName: file.downloadName,
    folderId,
    orderId: order.orderId,
  },
}));

// Flags customer photos with too few pixels for a detailed template, and carries the order details for the alerts
const MIN_SHORT_SIDE = 1400; // keep in step with MIN_RECOMMENDED_SIDE in shopify/assets/darlart-canvas-crop.js
const job = $('Wait for job').first().json.body;
const order = $('Loop over photos').first().json;
const source = (job.result && job.result.source) || {};
const shortSide = Math.min(source.width || 0, source.height || 0);
const warning = shortSide > 0 && shortSide < MIN_SHORT_SIDE
  ? `the customer's cropped photo is small (${source.width}x${source.height} px), check that the template keeps enough detail`
  : '';
return [{
  json: {
    orderId: order.orderId,
    shopifyOrderId: order.shopifyOrderId || '',
    customerEmail: order.customerEmail || '',
    format: order.format || '',
    colors: order.colors,
    warning,
    files: $input.all().length,
  },
}];

