// Collects what the customer receives: the printable PDF, the preview and the paint list (the SVG stays internal).
// Nothing is ever shared publicly: when the files are too heavy to email, only the PDF goes out and the owner is alerted.
const MAX_ATTACHMENT_BYTES = 15 * 1024 * 1024; // raw; base64 adds ~37%, and many SMTP relays stop at 20-25 MB
const WANTED = ['template.pdf', 'preview.png', 'palette.json'];
const ESSENTIAL = 'template.pdf';

const job = $('Wait for job').first().json.body;
const order = $('Loop over photos').first().json;
const listed = $('List output files').all().map((item) => item.json);
const downloads = $('Download file').all();
const folder = $('Create order folder').first().json;

const files = (job.result && job.result.files) || [];
const wanted = files.filter((file) => WANTED.includes(file.name));
const totalBytes = wanted.reduce((sum, file) => sum + (file.size || 0), 0);
const tooBig = totalBytes > MAX_ATTACHMENT_BYTES;
// too heavy for one email: send the printable PDF alone, the owner sends the rest
const toAttach = tooBig ? wanted.filter((file) => file.name === ESSENTIAL) : wanted;

// "Download file" runs once per listed file, so the binaries follow the order of "List output files"
const binary = {};
const attachments = [];
const missing = [];
for (const file of toAttach) {
  const index = listed.findIndex((entry) => entry.downloadName === file.downloadName || entry.url === file.url);
  const item = index >= 0 ? downloads[index] : null;
  if (!item || !item.binary || !item.binary.data) {
    missing.push(file.name);
    continue;
  }
  const key = `attachment${attachments.length}`;
  binary[key] = item.binary.data;
  attachments.push(key);
}

// what the owner needs to know: nothing attached at all, files dropped, or an email that must be completed by hand
const problem = attachments.length === 0
  ? `no file could be attached for order ${order.orderId} (${missing.join(', ') || 'no binary'})`
  : (tooBig ? `the files for order ${order.orderId} weigh ${Math.round(totalBytes / 1024 / 1024)} MB: only the PDF was emailed, send the preview and the paint list by hand` : '');

return [{
  json: {
    orderId: order.orderId,
    shopifyOrderId: order.shopifyOrderId || '',
    customerEmail: order.customerEmail || '',
    format: order.format || '',
    colors: order.colors,
    totalBytes,
    totalMb: Math.round((totalBytes / 1024 / 1024) * 10) / 10,
    tooBig,
    attachments: attachments.join(','),
    attachedCount: attachments.length,
    problem,
    driveFolderId: folder.id || '',
  },
  binary,
}];

